values ('kalima-1', 'kalima', 'kalimas', 'Kalima Tayyibah', 'لَا إِلَٰهَ إِلَّا ٱللَّٰهُ مُحَمَّدٌ رَسُولُ ٱللَّٰهِ', 'La ilaha illallah, Muhammadur Rasulullah.', 'None has the right to be worshipped except Allah. Muhammad is the messenger of Allah.', 'اللہ کے سوا کوئی معبود برحق نہیں۔ محمد اللہ کے رسول ہیں۔', null, null, 'The first of the six kalimas taught to children in South Asia. It is the wording of the testimony of faith, not a single numbered hadith by itself. Compare the Arabic with your printed textbook before approval.', 'needs_review', false, 4, 10, null, null, null, '{"lessonLearned":null}'::jsonb)
