insert into public.learning_content (id, kind, category, title, arabic, transliteration, translation_en, translation_ur, body_en, body_ur, source, review_status, verified, age_min, age_max, difficulty, repeat_count, reward_points, payload)
values ('kalima-3', 'kalima', 'kalimas', 'Kalima Tamjeed', 'سُبْحَانَ ٱللَّٰهِ وَٱلْحَمْدُ لِلَّٰهِ وَلَا إِلَٰهَ إِلَّا ٱللَّٰهُ وَٱللَّٰهُ أَكْبَرُ وَلَا حَوْلَ وَلَا قُوَّةَ إِلَّا بِٱللَّٰهِ ٱلْعَلِيِّ ٱلْعَظِيمِ', 'Subhanallahi walhamdu lillahi wa la ilaha illallahu wallahu akbar, wa la hawla wa la quwwata illa billahil aliyyil azeem.', 'Allah is free from every flaw, all praise is for Allah, none has the right to be worshipped except Allah, and Allah is the greatest. There is no power and no strength except with Allah, the Most High, the Most Great.', 'اللہ ہر نقص سے پاک ہے، تمام تعریف اللہ کے لیے ہے، اللہ کے سوا کوئی معبود نہیں، اور اللہ سب سے بڑا ہے۔ طاقت اور قوت صرف اللہ بلند و بزرگ کے ساتھ ہے۔', null, null, 'The third kalima, made of well-known phrases of dhikr. The combined wording is a textbook kalima, not one hadith. Compare it with your printed copy before approval.', 'needs_review', false, 6, 10, null, null, null, '{"lessonLearned":null}'::jsonb)
