insert into public.learning_content (id, kind, category, title, arabic, transliteration, translation_en, translation_ur, body_en, body_ur, source, review_status, verified, age_min, age_max, difficulty, repeat_count, reward_points, payload)
values ('kalima-5', 'kalima', 'kalimas', 'Kalima Istighfar', 'أَسْتَغْفِرُ ٱللَّٰهَ رَبِّي مِنْ كُلِّ ذَنْبٍ أَذْنَبْتُهُ عَمْدًا أَوْ خَطَأً سِرًّا أَوْ عَلَانِيَةً وَأَتُوبُ إِلَيْهِ مِنَ ٱلذَّنْبِ ٱلَّذِي أَعْلَمُ وَمِنَ ٱلذَّنْبِ ٱلَّذِي لَا أَعْلَمُ إِنَّكَ أَنْتَ عَلَّامُ ٱلْغُيُوبِ وَسَتَّارُ ٱلْعُيُوبِ وَغَفَّارُ ٱلذُّنُوبِ وَلَا حَوْلَ وَلَا قُوَّةَ إِلَّا بِٱللَّٰهِ ٱلْعَلِيِّ ٱلْعَظِيمِ', 'Astaghfirullaha rabbi min kulli dhambin adhnabtuhu amadan aw khataan sirran aw alaniyatan, wa atubu ilayhi minadh dhambilladhi alamu wa minadh dhambilladhi la alamu, innaka anta allamul ghuyubi wa sattarul uyubi wa ghaffarudh dhunubi, wa la hawla wa la quwwata illa billahil aliyyil azeem.', 'I ask Allah, my Lord, to forgive every sin I did on purpose or by mistake, in secret or in the open. I turn to Him from the sin I know and the sin I do not know. You know what is hidden, You cover faults, and You forgive sins. There is no power and no strength except with Allah, the Most High, the Most Great.', 'میں اپنے رب اللہ سے ہر اس گناہ کی معافی مانگتا ہوں جو میں نے جان بوجھ کر یا بھول کر، چھپ کر یا کھلے میں کیا۔ میں اس گناہ سے بھی توبہ کرتا ہوں جو میں جانتا ہوں اور اس سے بھی جو میں نہیں جانتا۔ تو چھپی باتوں کو جاننے والا، عیبوں کو چھپانے والا اور گناہ بخشنے والا ہے۔ طاقت صرف اللہ بلند و بزرگ کے ساتھ ہے۔', null, null, 'The fifth kalima. Printed children''s books do not all use the same Arabic for this kalima. This draft must be compared with the copy you want to teach. Not a claimed hadith reference.', 'needs_review', false, 7, 10, null, null, null, '{"lessonLearned":null}'::jsonb)
