insert into public.learning_content (id, kind, category, title, arabic, transliteration, translation_en, translation_ur, body_en, body_ur, source, review_status, verified, age_min, age_max, difficulty, repeat_count, reward_points, payload)
values ('kalima-6', 'kalima', 'kalimas', 'Kalima Radde Kufr', 'ٱللَّٰهُمَّ إِنِّي أَعُوذُ بِكَ مِنْ أَنْ أُشْرِكَ بِكَ شَيْئًا وَأَنَا أَعْلَمُ وَأَسْتَغْفِرُكَ لِمَا لَا أَعْلَمُ تُبْتُ عَنْهُ وَتَبَرَّأْتُ مِنَ ٱلْكُفْرِ وَٱلشِّرْكِ وَٱلْكِذْبِ وَٱلْغِيبَةِ وَٱلْبِدْعَةِ وَٱلنَّمِيمَةِ وَٱلْفَوَاحِشِ وَٱلْبُهْتَانِ وَٱلْمَعَاصِي كُلِّهَا وَأَسْلَمْتُ وَأَقُولُ لَا إِلَٰهَ إِلَّا ٱللَّٰهُ مُحَمَّدٌ رَسُولُ ٱللَّٰهِ', 'Allahumma inni a''udhu bika min an ushrika bika shay''an wa ana a''lamu, wa astaghfiruka lima la a''lamu, tubtu anhu wa tabarra''tu minal kufri wash shirki wal kidhbi wal ghibati wal bid''ati wan namimati wal fawahishi wal buhtani wal ma''asi kulliha, wa aslamtu wa aqulu la ilaha illallahu Muhammadur Rasulullah.', 'O Allah, I seek Your protection from associating anything with You while I know it, and I ask Your forgiveness for what I do not know. I turn away from disbelief, associating partners with You, lying, backbiting, innovation, tale-carrying, shameful acts, false blame, and every disobedience. I submit, and I say: none has the right to be worshipped except Allah, and Muhammad is the messenger of Allah.', 'اے اللہ، میں جان بوجھ کر کسی کو تیرا شریک بنانے سے تیری پناہ مانگتا ہوں، اور جو میں نہیں جانتا اس کی معافی مانگتا ہوں۔ میں کفر، شرک، جھوٹ، غیبت، بدعت، چغلی، برے کام، بہتان اور ہر نافرمانی سے بیزار ہوں۔ میں فرمانبردار ہوں اور کہتا ہوں کہ اللہ کے سوا کوئی معبود نہیں، محمد اللہ کے رسول ہیں۔', null, null, 'The sixth kalima. Its exact list of words varies between textbooks. This is a draft for comparison, not a verified narration. A reviewer must choose the wording your school uses.', 'needs_review', false, 8, 10, null, null, null, '{"lessonLearned":null}'::jsonb)
