insert into public.learning_content (id, kind, category, title, arabic, transliteration, translation_en, translation_ur, body_en, body_ur, source, review_status, verified, age_min, age_max, difficulty, repeat_count, reward_points, payload)
values ('morning-1', 'azkar', 'morning', 'Ayat al-Kursi in the morning', 'ٱللَّهُ لَآ إِلَٰهَ إِلَّا هُوَ ٱلْحَىُّ ٱلْقَيُّومُ ۚ لَا تَأْخُذُهُۥ سِنَةٌۭ وَلَا نَوْمٌۭ ۚ لَّهُۥ مَا فِى ٱلسَّمَٰوَٰتِ وَمَا فِى ٱلْأَرْضِ ۗ مَن ذَا ٱلَّذِى يَشْفَعُ عِندَهُۥٓ إِلَّا بِإِذْنِهِۦ ۚ يَعْلَمُ مَا بَيْنَ أَيْدِيهِمْ وَمَا خَلْفَهُمْ ۖ وَلَا يُحِيطُونَ بِشَىْءٍۢ مِّنْ عِلْمِهِۦٓ إِلَّا بِمَا شَآءَ ۚ وَسِعَ كُرْسِيُّهُ ٱلسَّمَٰوَٰتِ وَٱلْأَرْضَ ۖ وَلَا يَـُٔودُهُۥ حِفْظُهُمَا ۚ وَهُوَ ٱلْعَلِىُّ ٱلْعَظِيمُ', 'Allahu la ilaha illa huwal hayyul qayyum. Read the rest slowly with a parent.', 'Allah - none has the right to be worshipped except Him, the Ever-Living, the Sustainer. A parent can help with the full meaning.', 'اللہ، اس کے سوا کوئی معبود نہیں، وہ ہمیشہ زندہ ہے اور سب کو قائم رکھنے والا ہے۔ پوری آیت کا مطلب بڑے کے ساتھ سنیں۔', null, null, 'Quran 2:255. Arabic, Saheeh International English, and Fateh Muhammad Jalandhry Urdu were copied from api.alquran.cloud on 2026-10-20. Compare them with a printed mushaf before approval. Reading it in the morning is taught from hadith collections; confirm that hadith before fixing a count.', 'needs_review', false, 6, 10, null, 1, null, '{"lessonLearned":null}'::jsonb)
