values ('morning-7', 'azkar', 'morning', 'A short morning praise', 'سُبْحَانَ ٱللَّٰهِ وَبِحَمْدِهِ', 'Subhana Allahi wa bihamdih.', 'Allah is free from every flaw, and I praise Him.', 'اللہ ہر نقص سے پاک ہے اور میں اس کی تعریف کرتا ہوں۔', null, null, 'Draft wording for a parent or teacher to compare with a trusted book. Not marked verified. A short dhikr taught in authentic collections. Confirm the report and the recommended count before approval.', 'needs_review', false, 4, 10, null, 1, null, '{"lessonLearned":null}'::jsonb)
