values ('morning-8', 'azkar', 'morning', 'Asking for a good day', 'ٱللَّٰهُمَّ إِنِّي أَسْأَلُكَ خَيْرَ هَٰذَا ٱلْيَوْمِ', 'Allahumma inni as''aluka khayra hadhal yawm.', 'O Allah, I ask You for the good of this day.', 'اے اللہ، میں تجھ سے اس دن کی بھلائی مانگتا ہوں۔', null, null, 'Draft wording for a parent or teacher to compare with a trusted book. Not marked verified. A short morning asking. Confirm the fuller dua in a hadith book before teaching a longer version.', 'needs_review', false, 5, 10, null, 1, null, '{"lessonLearned":null}'::jsonb)
