values ('sleeping-4', 'azkar', 'sleeping', 'Surah Al-Falaq before sleep', 'بِسْمِ ٱللَّهِ ٱلرَّحْمَٰنِ ٱلرَّحِيمِ قُلْ أَعُوذُ بِرَبِّ ٱلْفَلَقِ
