values ('drinking-1', 'azkar', 'drinking', 'Before drinking', 'بِسْمِ ٱللَّهِ ٱلرَّحْمَٰنِ ٱلرَّحِيمِ', 'Bismillah.', 'In the name of Allah, before a drink.', 'پینے سے پہلے اللہ کے نام سے۔', null, null, 'Quran 1:1 for the basmala. Arabic, Saheeh International English, and Fateh Muhammad Jalandhry Urdu were copied from api.alquran.cloud on 2026-10-20. Compare them with a printed mushaf before approval. The manners of saying it before drinking should be confirmed from a hadith or fiqh book your family follows.', 'needs_review', false, 3, 10, null, 1, null, '{"lessonLearned":null}'::jsonb)
