values ('drinking-2', 'azkar', 'drinking', 'After drinking', 'ٱلْحَمْدُ لِلَّٰهِ', 'Al-hamdu lillah.', 'All praise belongs to Allah, after a drink.', 'پینے کے بعد تمام تعریف اللہ کے لیے ہے۔', null, null, 'Draft wording for a parent or teacher to compare with a trusted book. Not marked verified. A short thanks. Do not present it as a unique numbered hadith until it is checked.', 'needs_review', false, 3, 10, null, 1, null, '{"lessonLearned":null}'::jsonb)
