values ('entering-home-2', 'azkar', 'entering-home', 'Salam at the door', 'ٱلسَّلَامُ عَلَيْكُمْ', 'Assalamu alaykum.', 'Peace be upon you. Say this to the people in the house.', 'آپ پر سلامتی ہو۔ گھر والوں کو یہ کہیں۔', null, null, 'Draft wording for a parent or teacher to compare with a trusted book. Not marked verified. The greeting of salam. A reviewer should add the Quran or hadith reference they want children to learn.', 'needs_review', false, 3, 10, null, 1, null, '{"lessonLearned":null}'::jsonb)
