values ('leaving-home-2', 'azkar', 'leaving-home', 'A short leaving phrase', 'تَوَكَّلْتُ عَلَى ٱللَّٰهِ', 'Tawakkaltu alallah.', 'I rely on Allah.', 'میں نے اللہ پر بھروسہ کیا۔', null, null, 'Draft wording for a parent or teacher to compare with a trusted book. Not marked verified. A short phrase from the longer leaving dua. Do not present the short phrase as the full hadith.', 'needs_review', false, 4, 10, null, 1, null, '{"lessonLearned":null}'::jsonb)
