insert into public.learning_content (id, kind, category, title, arabic, transliteration, translation_en, translation_ur, body_en, body_ur, source, review_status, verified, age_min, age_max, difficulty, repeat_count, reward_points, payload)
values ('after-prayer-5', 'azkar', 'after-prayer', 'After-prayer greatness', 'ٱللَّٰهُ أَكْبَرُ', 'Allahu akbar.', 'Allah is the greatest. Families often complete the set with thirty-three or thirty-four. A reviewer must choose the count from a checked hadith.', 'اللہ سب سے بڑا ہے۔ کچھ گھر تینتیس اور کچھ چونتیس مکمل کرتے ہیں۔ تعداد چیک شدہ حدیث سے طے کریں۔', null, null, 'Draft wording for a parent or teacher to compare with a trusted book. Not marked verified. The count at the end of this dhikr is reported with a small difference. Do not freeze one number until the hadith is checked.', 'needs_review', false, 6, 10, null, 33, null, '{"lessonLearned":null}'::jsonb)
