insert into public.learning_content (id, kind, category, title, arabic, transliteration, translation_en, translation_ur, body_en, body_ur, source, review_status, verified, age_min, age_max, difficulty, repeat_count, reward_points, payload)
values ('after-prayer-6', 'azkar', 'after-prayer', 'Ayat al-Kursi after prayer', 'ٱللَّهُ لَآ إِلَٰهَ إِلَّا هُوَ ٱلْحَىُّ ٱلْقَيُّومُ ۚ لَا تَأْخُذُهُۥ سِنَةٌۭ وَلَا نَوْمٌۭ ۚ لَّهُۥ مَا فِى ٱلسَّمَٰوَٰتِ وَمَا فِى ٱلْأَرْضِ ۗ مَن ذَا ٱلَّذِى يَشْفَعُ عِندَهُۥٓ إِلَّا بِإِذْنِهِۦ ۚ يَعْلَمُ مَا بَيْنَ أَيْدِيهِمْ وَمَا خَلْفَهُمْ ۖ وَلَا يُحِيطُونَ بِشَىْءٍۢ مِّنْ عِلْمِهِۦٓ إِلَّا بِمَا شَآءَ ۚ وَسِعَ كُرْسِيُّهُ ٱلسَّمَٰوَٰتِ وَٱلْأَرْضَ ۖ وَلَا يَـُٔودُهُۥ حِفْظُهُمَا ۚ وَهُوَ ٱلْعَلِىُّ ٱلْعَظِيمُ', 'Allahu la ilaha illa huwal hayyul qayyum.', 'Read Ayat al-Kursi once after the prayer, with a parent if the child is still learning it.', 'نماز کے بعد آیت الکرسی ایک بار پڑھیں، سیکھتے ہوئے بڑے کے ساتھ۔', null, null, 'Quran 2:255. Arabic, Saheeh International English, and Fateh Muhammad Jalandhry Urdu were copied from api.alquran.cloud on 2026-10-20. Compare them with a printed mushaf before approval. Reports about reading it after every prayer need a graded reference before approval.', 'needs_review', false, 7, 10, null, 1, null, '{"lessonLearned":null}'::jsonb)
