values ('after-prayer-8', 'azkar', 'after-prayer', 'A quiet thanks after prayer', 'ٱلْحَمْدُ لِلَّٰهِ', 'Al-hamdu lillah.', 'All praise belongs to Allah. Sit calmly for a moment after the prayer.', 'تمام تعریف اللہ کے لیے ہے۔ نماز کے بعد ایک لمحہ خاموش بیٹھیں۔', null, null, 'Draft wording for a parent or teacher to compare with a trusted book. Not marked verified. A simple thanks for children. It is not a replacement for the dhikr above.', 'needs_review', false, 4, 10, null, 1, null, '{"lessonLearned":null}'::jsonb)
