values ('quiz-4', 'quiz', 'kalimas', 'One Allah', '', '', 'The kalimas teach us to worship how many gods?', 'کلمے کتنے معبودوں کی عبادت سکھاتے ہیں؟', 'Muslims worship Allah alone.', 'مسلمان صرف اللہ کی عبادت کرتے ہیں۔', 'Basic Islamic teaching for children. A reviewer should attach the exact Quran or hadith reference before this is called verified.', 'needs_review', false, 5, 10, 'easy', null, null, '{"options":[{"id":"a","text":"One","icon":"sun","imageUrl":null},{"id":"b","text":"Two","icon":"heart","imageUrl":null},{"id":"c","text":"Three","icon":"star","imageUrl":null},{"id":"d","text":"Four","icon":"cloud","imageUrl":null}],"explanation":"Muslims worship Allah alone.","explanationUr":"مسلمان صرف اللہ کی عبادت کرتے ہیں۔","lessonLearned":null}'::jsonb)
