values ('quiz-6', 'quiz', 'kalimas', 'Praise', '', '', 'Where does praise belong in the third kalima?', 'تیسرے کلمے میں تعریف کس کے لیے ہے؟', 'Alhamdu lillah means all praise is for Allah.', 'الحمد للہ کا مطلب ہے تمام تعریف اللہ کے لیے ہے۔', 'Basic Islamic teaching for children. A reviewer should attach the exact Quran or hadith reference before this is called verified.', 'needs_review', false, 7, 10, 'growing', null, null, '{"options":[{"id":"a","text":"For people only","icon":"sun","imageUrl":null},{"id":"b","text":"For Allah","icon":"heart","imageUrl":null},{"id":"c","text":"For statues","icon":"star","imageUrl":null},{"id":"d","text":"For no one","icon":"cloud","imageUrl":null}],"explanation":"Alhamdu lillah means all praise is for Allah.","explanationUr":"الحمد للہ کا مطلب ہے تمام تعریف اللہ کے لیے ہے۔","lessonLearned":null}'::jsonb)
