values ('quiz-7', 'quiz', 'kalimas', 'The greatest', '', '', 'What does "Allahu akbar" mean?', '"اللہ اکبر" کا مطلب کیا ہے؟', 'Akbar here means greater than everything else.', 'اکبر کا مطلب ہے وہ سب سے بڑا ہے۔', 'Basic Islamic teaching for children. A reviewer should attach the exact Quran or hadith reference before this is called verified.', 'needs_review', false, 5, 10, 'easy', null, null, '{"options":[{"id":"a","text":"Allah is the greatest","icon":"sun","imageUrl":null},{"id":"b","text":"Allah is tired","icon":"heart","imageUrl":null},{"id":"c","text":"Allah is two","icon":"star","imageUrl":null},{"id":"d","text":"Allah is hidden from mercy","icon":"cloud","imageUrl":null}],"explanation":"Akbar here means greater than everything else.","explanationUr":"اکبر کا مطلب ہے وہ سب سے بڑا ہے۔","lessonLearned":null}'::jsonb)
