values ('quiz-8', 'quiz', 'kalimas', 'Forgiveness', '', '', 'The fifth kalima is mainly about what?', 'پانچواں کلمہ زیادہ تر کس کے بارے میں ہے؟', 'Istighfar means asking Allah for forgiveness.', 'استغفار کا مطلب اللہ سے معافی مانگنا ہے۔', 'Basic Islamic teaching for children. A reviewer should attach the exact Quran or hadith reference before this is called verified.', 'needs_review', false, 5, 10, 'easy', null, null, '{"options":[{"id":"a","text":"Asking Allah to forgive","icon":"sun","imageUrl":null},{"id":"b","text":"Buying a toy","icon":"heart","imageUrl":null},{"id":"c","text":"Counting clouds","icon":"star","imageUrl":null},{"id":"d","text":"Drawing a house","icon":"cloud","imageUrl":null}],"explanation":"Istighfar means asking Allah for forgiveness.","explanationUr":"استغفار کا مطلب اللہ سے معافی مانگنا ہے۔","lessonLearned":null}'::jsonb)
