values ('quiz-11', 'quiz', 'manners', 'Greeting', '', '', 'What do Muslims say when they meet?', 'ملتے وقت مسلمان کیا کہتے ہیں؟', 'Salam is a prayer for peace.', 'سلام امن کی دعا ہے۔', 'Basic Islamic teaching for children. A reviewer should attach the exact Quran or hadith reference before this is called verified.', 'needs_review', false, 7, 10, 'growing', null, null, '{"options":[{"id":"a","text":"Assalamu alaykum","icon":"sun","imageUrl":null},{"id":"b","text":"Goodbye forever","icon":"heart","imageUrl":null},{"id":"c","text":"Go away","icon":"star","imageUrl":null},{"id":"d","text":"Be quiet always","icon":"cloud","imageUrl":null}],"explanation":"Salam is a prayer for peace.","explanationUr":"سلام امن کی دعا ہے۔","lessonLearned":null}'::jsonb)
