values ('quiz-12', 'quiz', 'manners', 'Reply', '', '', 'If someone gives you salam, what should you do?', 'اگر کوئی سلام کہے تو کیا کرنا چاہیے؟', 'A greeting should be answered. See Quran 4:86 and confirm the verse before approval.', 'سلام کا جواب دینا چاہیے۔ سورۃ النساء 86 دیکھ کر تصدیق کریں۔', 'Basic Islamic teaching for children. A reviewer should attach the exact Quran or hadith reference before this is called verified.', 'needs_review', false, 5, 10, 'easy', null, null, '{"options":[{"id":"a","text":"Hide","icon":"sun","imageUrl":null},{"id":"b","text":"Reply with salam","icon":"heart","imageUrl":null},{"id":"c","text":"Shout","icon":"star","imageUrl":null},{"id":"d","text":"Turn your back","icon":"cloud","imageUrl":null}],"explanation":"A greeting should be answered. See Quran 4:86 and confirm the verse before approval.","explanationUr":"سلام کا جواب دینا چاہیے۔ سورۃ النساء 86 دیکھ کر تصدیق کریں۔","lessonLearned":null}'::jsonb)
