values ('quiz-15', 'quiz', 'manners', 'Sharing', '', '', 'Your friend has no crayon. What is kind?', 'دوست کے پاس کریون نہیں۔ مہربانی کیا ہے؟', 'Sharing is a basic good manner.', 'بانٹنا ایک اچھا ادب ہے۔', 'Basic Islamic teaching for children. A reviewer should attach the exact Quran or hadith reference before this is called verified.', 'needs_review', false, 5, 10, 'easy', null, null, '{"options":[{"id":"a","text":"Share one","icon":"sun","imageUrl":null},{"id":"b","text":"Hide all of them","icon":"heart","imageUrl":null},{"id":"c","text":"Laugh","icon":"star","imageUrl":null},{"id":"d","text":"Break them","icon":"cloud","imageUrl":null}],"explanation":"Sharing is a basic good manner.","explanationUr":"بانٹنا ایک اچھا ادب ہے۔","lessonLearned":null}'::jsonb)
