values ('quiz-17', 'quiz', 'manners', 'Listening', '', '', 'When a parent is speaking, a kind child does what?', 'جب والدین بول رہے ہوں تو مہربان بچہ کیا کرتا ہے؟', 'Listening is part of respect.', 'سننا عزت کا حصہ ہے۔', 'Basic Islamic teaching for children. A reviewer should attach the exact Quran or hadith reference before this is called verified.', 'needs_review', false, 5, 10, 'easy', null, null, '{"options":[{"id":"a","text":"Listens","icon":"sun","imageUrl":null},{"id":"b","text":"Covers both ears","icon":"heart","imageUrl":null},{"id":"c","text":"Interrupts for fun","icon":"star","imageUrl":null},{"id":"d","text":"Runs off","icon":"cloud","imageUrl":null}],"explanation":"Listening is part of respect.","explanationUr":"سننا عزت کا حصہ ہے۔","lessonLearned":null}'::jsonb)
