values ('quiz-18', 'quiz', 'manners', 'Sorry', '', '', 'If you bump someone, what do you say?', 'اگر کسی سے ٹکرا جاؤ تو کیا کہو؟', 'A small apology keeps peace.', 'معافی سلامتی رکھتی ہے۔', 'Basic Islamic teaching for children. A reviewer should attach the exact Quran or hadith reference before this is called verified.', 'needs_review', false, 5, 10, 'easy', null, null, '{"options":[{"id":"a","text":"Sorry","icon":"sun","imageUrl":null},{"id":"b","text":"Nothing","icon":"heart","imageUrl":null},{"id":"c","text":"It was your fault","icon":"star","imageUrl":null},{"id":"d","text":"Move","icon":"cloud","imageUrl":null}],"explanation":"A small apology keeps peace.","explanationUr":"معافی سلامتی رکھتی ہے۔","lessonLearned":null}'::jsonb)
