values ('quiz-19', 'quiz', 'manners', 'Mosque voice', '', '', 'Inside the mosque, which voice is better?', 'مسجد میں کون سی آواز بہتر ہے؟', 'The mosque is a place for prayer and calm.', 'مسجد نماز اور سکون کی جگہ ہے۔', 'Basic Islamic teaching for children. A reviewer should attach the exact Quran or hadith reference before this is called verified.', 'needs_review', false, 5, 10, 'easy', null, null, '{"options":[{"id":"a","text":"A quiet voice","icon":"sun","imageUrl":null},{"id":"b","text":"A shouting game","icon":"heart","imageUrl":null},{"id":"c","text":"A drum","icon":"star","imageUrl":null},{"id":"d","text":"A race","icon":"cloud","imageUrl":null}],"explanation":"The mosque is a place for prayer and calm.","explanationUr":"مسجد نماز اور سکون کی جگہ ہے۔","lessonLearned":null}'::jsonb)
