values ('quiz-20', 'quiz', 'manners', 'Clean hands', '', '', 'Before eating, what should you do?', 'کھانے سے پہلے کیا کرنا چاہیے؟', 'Clean hands are a health and cleanliness lesson.', 'صاف ہاتھ صفائی کا سبق ہیں۔', 'Basic Islamic teaching for children. A reviewer should attach the exact Quran or hadith reference before this is called verified.', 'needs_review', false, 5, 10, 'easy', null, null, '{"options":[{"id":"a","text":"Wash your hands","icon":"sun","imageUrl":null},{"id":"b","text":"Wipe them on the floor","icon":"heart","imageUrl":null},{"id":"c","text":"Hide them","icon":"star","imageUrl":null},{"id":"d","text":"Skip water","icon":"cloud","imageUrl":null}],"explanation":"Clean hands are a health and cleanliness lesson.","explanationUr":"صاف ہاتھ صفائی کا سبق ہیں۔","lessonLearned":null}'::jsonb)
