values ('quiz-21', 'quiz', 'manners', 'Thanks', '', '', 'When someone helps you, what do you say?', 'جب کوئی مدد کرے تو کیا کہتے ہو؟', 'Gratitude is for people and, more deeply, for Allah.', 'شکر لوگوں کا بھی ہے اور اصل میں اللہ کا بھی۔', 'Basic Islamic teaching for children. A reviewer should attach the exact Quran or hadith reference before this is called verified.', 'needs_review', false, 7, 10, 'growing', null, null, '{"options":[{"id":"a","text":"Thank you","icon":"sun","imageUrl":null},{"id":"b","text":"Go away","icon":"heart","imageUrl":null},{"id":"c","text":"Mine","icon":"star","imageUrl":null},{"id":"d","text":"No","icon":"cloud","imageUrl":null}],"explanation":"Gratitude is for people and, more deeply, for Allah.","explanationUr":"شکر لوگوں کا بھی ہے اور اصل میں اللہ کا بھی۔","lessonLearned":null}'::jsonb)
