values ('quiz-22', 'quiz', 'manners', 'Animals', '', '', 'How should we treat a cat or a bird?', 'بلی یا پرندے کے ساتھ کیسا برتاؤ کریں؟', 'Kindness to animals is part of good character. A reviewer can add a checked hadith.', 'جانوروں پر مہربانی اچھے اخلاق میں ہے', 'Basic Islamic teaching for children. A reviewer should attach the exact Quran or hadith reference before this is called verified.', 'needs_review', false, 5, 10, 'easy', null, null, '{"options":[{"id":"a","text":"Gently","icon":"sun","imageUrl":null},{"id":"b","text":"By pulling a tail","icon":"heart","imageUrl":null},{"id":"c","text":"By throwing stones","icon":"star","imageUrl":null},{"id":"d","text":"By shouting at it","icon":"cloud","imageUrl":null}],"explanation":"Kindness to animals is part of good character. A reviewer can add a checked hadith.","explanationUr":"جانوروں پر مہربانی اچھے اخلاق میں ہے","lessonLearned":null}'::jsonb)
