values ('quiz-30', 'quiz', 'prayer', 'Sunset', '', '', 'Which prayer comes just after sunset?', 'غروبِ آفتاب کے بعد کون سی نماز ہے؟', 'Maghrib is the sunset prayer.', 'مغرب غروب کی نماز ہے۔', 'Basic Islamic teaching for children. A reviewer should attach the exact Quran or hadith reference before this is called verified.', 'needs_review', false, 5, 10, 'easy', null, null, '{"options":[{"id":"a","text":"Maghrib","icon":"sun","imageUrl":null},{"id":"b","text":"Fajr","icon":"heart","imageUrl":null},{"id":"c","text":"Zuhr","icon":"star","imageUrl":null},{"id":"d","text":"Duha only","icon":"cloud","imageUrl":null}],"explanation":"Maghrib is the sunset prayer.","explanationUr":"مغرب غروب کی نماز ہے۔","lessonLearned":null}'::jsonb)
