values ('quiz-31', 'quiz', 'prayer', 'Night', '', '', 'Which prayer comes at night?', 'رات کو کون سی نماز ہے؟', 'Isha is the night prayer.', 'عشاء رات کی نماز ہے۔', 'Basic Islamic teaching for children. A reviewer should attach the exact Quran or hadith reference before this is called verified.', 'needs_review', false, 7, 10, 'growing', null, null, '{"options":[{"id":"a","text":"Isha","icon":"sun","imageUrl":null},{"id":"b","text":"Fajr","icon":"heart","imageUrl":null},{"id":"c","text":"Zuhr","icon":"star","imageUrl":null},{"id":"d","text":"Asr","icon":"cloud","imageUrl":null}],"explanation":"Isha is the night prayer.","explanationUr":"عشاء رات کی نماز ہے۔","lessonLearned":null}'::jsonb)
