values ('quiz-32', 'quiz', 'prayer', 'Direction', '', '', 'Which way do Muslims face for salah?', 'نماز میں مسلمان کس طرف رخ کرتے ہیں؟', 'The qibla is the direction of the Kaaba.', 'قبلہ خانہ کعبہ کی سمت ہے۔', 'Basic Islamic teaching for children. A reviewer should attach the exact Quran or hadith reference before this is called verified.', 'needs_review', false, 5, 10, 'easy', null, null, '{"options":[{"id":"a","text":"Toward the Kaaba in Makkah","icon":"sun","imageUrl":null},{"id":"b","text":"Toward the nearest shop","icon":"heart","imageUrl":null},{"id":"c","text":"Toward the sun always","icon":"star","imageUrl":null},{"id":"d","text":"Any statue","icon":"cloud","imageUrl":null}],"explanation":"The qibla is the direction of the Kaaba.","explanationUr":"قبلہ خانہ کعبہ کی سمت ہے۔","lessonLearned":null}'::jsonb)
