values ('quiz-35', 'quiz', 'prayer', 'Arms', '', '', 'How far are the arms washed in that verse?', 'اس آیت میں ہاتھ کہاں تک دھوئے جاتے ہیں؟', 'Quran 5:6 says to the elbows.', 'سورۃ المائدہ 6 میں کہنیوں تک کا ذکر ہے۔', 'Basic Islamic teaching for children. A reviewer should attach the exact Quran or hadith reference before this is called verified.', 'needs_review', false, 5, 10, 'easy', null, null, '{"options":[{"id":"a","text":"To the elbows","icon":"sun","imageUrl":null},{"id":"b","text":"Only the fingers","icon":"heart","imageUrl":null},{"id":"c","text":"Only the shoulders","icon":"star","imageUrl":null},{"id":"d","text":"They are not washed","icon":"cloud","imageUrl":null}],"explanation":"Quran 5:6 says to the elbows.","explanationUr":"سورۃ المائدہ 6 میں کہنیوں تک کا ذکر ہے۔","lessonLearned":null}'::jsonb)
