values ('quiz-36', 'quiz', 'prayer', 'Head', '', '', 'What does the wudu verse say about the head?', 'وضو کی آیت سر کے بارے میں کیا کہتی ہے؟', 'The verse says to wipe over your heads.', 'آیت میں سر کا مسح کرنے کو کہا گیا ہے۔', 'Basic Islamic teaching for children. A reviewer should attach the exact Quran or hadith reference before this is called verified.', 'needs_review', false, 7, 10, 'growing', null, null, '{"options":[{"id":"a","text":"Wipe over it","icon":"sun","imageUrl":null},{"id":"b","text":"Cover it with food","icon":"heart","imageUrl":null},{"id":"c","text":"Do not touch it ever","icon":"star","imageUrl":null},{"id":"d","text":"Shave it during wudu","icon":"cloud","imageUrl":null}],"explanation":"The verse says to wipe over your heads.","explanationUr":"آیت میں سر کا مسح کرنے کو کہا گیا ہے۔","lessonLearned":null}'::jsonb)
