values ('quiz-38', 'quiz', 'prayer', 'Calm', '', '', 'During salah, which body is better?', 'نماز میں کون سا بدن بہتر ہے؟', 'Salah is quiet worship.', 'نماز خاموش عبادت ہے۔', 'Basic Islamic teaching for children. A reviewer should attach the exact Quran or hadith reference before this is called verified.', 'needs_review', false, 5, 10, 'easy', null, null, '{"options":[{"id":"a","text":"A calm, still body","icon":"sun","imageUrl":null},{"id":"b","text":"A jumping body","icon":"heart","imageUrl":null},{"id":"c","text":"A spinning body","icon":"star","imageUrl":null},{"id":"d","text":"A body that pushes friends","icon":"cloud","imageUrl":null}],"explanation":"Salah is quiet worship.","explanationUr":"نماز خاموش عبادت ہے۔","lessonLearned":null}'::jsonb)
