values ('quiz-39', 'quiz', 'prayer', 'Rows', '', '', 'In a group prayer, children should do what?', 'جماعت میں بچوں کو کیا کرنا چاہیے؟', 'The row is straight and calm.', 'صف سیدھی اور پُرسکون ہوتی ہے۔', 'Basic Islamic teaching for children. A reviewer should attach the exact Quran or hadith reference before this is called verified.', 'needs_review', false, 5, 10, 'easy', null, null, '{"options":[{"id":"a","text":"Stand in the row calmly","icon":"sun","imageUrl":null},{"id":"b","text":"Start a race","icon":"heart","imageUrl":null},{"id":"c","text":"Talk through the prayer","icon":"star","imageUrl":null},{"id":"d","text":"Block the door","icon":"cloud","imageUrl":null}],"explanation":"The row is straight and calm.","explanationUr":"صف سیدھی اور پُرسکون ہوتی ہے۔","lessonLearned":null}'::jsonb)
