values ('quiz-40', 'quiz', 'prayer', 'Learning', '', '', 'If you do not know the words yet, what is right?', 'اگر الفاظ ابھی نہ آئیں تو کیا ٹھیک ہے؟', 'A child learns with a parent. We do not invent Quranic words.', 'بچہ والدین کے ساتھ سیکھتا ہے۔ قرآنی الفاظ خود نہیں بناتے۔', 'Basic Islamic teaching for children. A reviewer should attach the exact Quran or hadith reference before this is called verified.', 'needs_review', false, 5, 10, 'easy', null, null, '{"options":[{"id":"a","text":"Pray beside a parent and keep learning","icon":"sun","imageUrl":null},{"id":"b","text":"Make up Arabic","icon":"heart","imageUrl":null},{"id":"c","text":"Skip wudu","icon":"star","imageUrl":null},{"id":"d","text":"Invent a verse","icon":"cloud","imageUrl":null}],"explanation":"A child learns with a parent. We do not invent Quranic words.","explanationUr":"بچہ والدین کے ساتھ سیکھتا ہے۔ قرآنی الفاظ خود نہیں بناتے۔","lessonLearned":null}'::jsonb)
