values ('quiz-42', 'quiz', 'basic-knowledge', 'First pillar', '', '', 'Which pillar is the testimony of faith?', 'کون سا ستون کلمۂ شہادت ہے؟', 'The shahada is the first of the five.', 'شہادت پانچ میں پہلا ستون ہے۔', 'Basic Islamic teaching for children. A reviewer should attach the exact Quran or hadith reference before this is called verified.', 'needs_review', false, 5, 10, 'easy', null, null, '{"options":[{"id":"a","text":"Shahada","icon":"sun","imageUrl":null},{"id":"b","text":"Hajj only","icon":"heart","imageUrl":null},{"id":"c","text":"Zakat only","icon":"star","imageUrl":null},{"id":"d","text":"Sawm only","icon":"cloud","imageUrl":null}],"explanation":"The shahada is the first of the five.","explanationUr":"شہادت پانچ میں پہلا ستون ہے۔","lessonLearned":null}'::jsonb)
