values ('quiz-44', 'quiz', 'basic-knowledge', 'Charity', '', '', 'What is zakat?', 'زکوٰۃ کیا ہے؟', 'Zakat is a pillar. The details of who pays it are for a parent or teacher.', 'زکوٰۃ ایک ستون ہے۔ کس پر فرض ہے، یہ والدین یا استاد بتائیں۔', 'Basic Islamic teaching for children. A reviewer should attach the exact Quran or hadith reference before this is called verified.', 'needs_review', false, 5, 10, 'easy', null, null, '{"options":[{"id":"a","text":"Obligatory charity for those who must pay it","icon":"sun","imageUrl":null},{"id":"b","text":"A game score","icon":"heart","imageUrl":null},{"id":"c","text":"A type of shoe","icon":"star","imageUrl":null},{"id":"d","text":"A song","icon":"cloud","imageUrl":null}],"explanation":"Zakat is a pillar. The details of who pays it are for a parent or teacher.","explanationUr":"زکوٰۃ ایک ستون ہے۔ کس پر فرض ہے، یہ والدین یا استاد بتائیں۔","lessonLearned":null}'::jsonb)
