values ('quiz-45', 'quiz', 'basic-knowledge', 'Journey', '', '', 'Hajj is a journey to which city?', 'حج کس شہر کا سفر ہے؟', 'Hajj is to Makkah, once in a lifetime for the person who is able.', 'حج مکہ کا سفر ہے، جو شخص قادر ہو اس پر زندگی میں ایک بار۔', 'Basic Islamic teaching for children. A reviewer should attach the exact Quran or hadith reference before this is called verified.', 'needs_review', false, 5, 10, 'easy', null, null, '{"options":[{"id":"a","text":"Makkah","icon":"sun","imageUrl":null},{"id":"b","text":"Cairo","icon":"heart","imageUrl":null},{"id":"c","text":"Istanbul","icon":"star","imageUrl":null},{"id":"d","text":"Delhi","icon":"cloud","imageUrl":null}],"explanation":"Hajj is to Makkah, once in a lifetime for the person who is able.","explanationUr":"حج مکہ کا سفر ہے، جو شخص قادر ہو اس پر زندگی میں ایک بار۔","lessonLearned":null}'::jsonb)
