values ('quiz-46', 'quiz', 'basic-knowledge', 'Book', '', '', 'What is the holy book of Islam?', 'اسلام کی مقدس کتاب کیا ہے؟', 'The Quran is Allah''s revealed book.', 'قرآن اللہ کی اتاری ہوئی کتاب ہے۔', 'Basic Islamic teaching for children. A reviewer should attach the exact Quran or hadith reference before this is called verified.', 'needs_review', false, 7, 10, 'growing', null, null, '{"options":[{"id":"a","text":"The Quran","icon":"sun","imageUrl":null},{"id":"b","text":"A storybook we invent","icon":"heart","imageUrl":null},{"id":"c","text":"A newspaper","icon":"star","imageUrl":null},{"id":"d","text":"A map only","icon":"cloud","imageUrl":null}],"explanation":"The Quran is Allah''s revealed book.","explanationUr":"قرآن اللہ کی اتاری ہوئی کتاب ہے۔","lessonLearned":null}'::jsonb)
