values ('quiz-47', 'quiz', 'basic-knowledge', 'Prophet', '', '', 'Who received the Quran?', 'قرآن کس پر اترا؟', 'Allah revealed the Quran to Muhammad through Jibril.', 'اللہ نے قرآن محمد پر جبریل کے ذریعے اتارا۔', 'Basic Islamic teaching for children. A reviewer should attach the exact Quran or hadith reference before this is called verified.', 'needs_review', false, 5, 10, 'easy', null, null, '{"options":[{"id":"a","text":"Prophet Muhammad","icon":"sun","imageUrl":null},{"id":"b","text":"Prophet Nuh only","icon":"heart","imageUrl":null},{"id":"c","text":"Prophet Yusuf only","icon":"star","imageUrl":null},{"id":"d","text":"A king in Rome","icon":"cloud","imageUrl":null}],"explanation":"Allah revealed the Quran to Muhammad through Jibril.","explanationUr":"اللہ نے قرآن محمد پر جبریل کے ذریعے اتارا۔","lessonLearned":null}'::jsonb)
