values ('quiz-50', 'quiz', 'basic-knowledge', 'Madinah', '', '', 'To which city did the Prophet move in the Hijrah?', 'ہجرت میں نبی کس شہر گئے؟', 'The Hijrah was from Makkah to Madinah.', 'ہجرت مکہ سے مدینہ کی طرف تھی۔', 'Basic Islamic teaching for children. A reviewer should attach the exact Quran or hadith reference before this is called verified.', 'needs_review', false, 5, 10, 'easy', null, null, '{"options":[{"id":"a","text":"Madinah","icon":"sun","imageUrl":null},{"id":"b","text":"A desert with no name","icon":"heart","imageUrl":null},{"id":"c","text":"Rome","icon":"star","imageUrl":null},{"id":"d","text":"China","icon":"cloud","imageUrl":null}],"explanation":"The Hijrah was from Makkah to Madinah.","explanationUr":"ہجرت مکہ سے مدینہ کی طرف تھی۔","lessonLearned":null}'::jsonb)
