values ('quiz-54', 'quiz', 'basic-knowledge', 'Alhamdulillah', '', '', 'When do we say Alhamdulillah?', 'الحمد للہ کب کہتے ہیں؟', 'It means all praise belongs to Allah.', 'اس کا مطلب ہے تمام تعریف اللہ کے لیے ہے۔', 'Basic Islamic teaching for children. A reviewer should attach the exact Quran or hadith reference before this is called verified.', 'needs_review', false, 5, 10, 'easy', null, null, '{"options":[{"id":"a","text":"When we thank Allah","icon":"sun","imageUrl":null},{"id":"b","text":"When we want to scare someone","icon":"heart","imageUrl":null},{"id":"c","text":"When we lie","icon":"star","imageUrl":null},{"id":"d","text":"When we waste food","icon":"cloud","imageUrl":null}],"explanation":"It means all praise belongs to Allah.","explanationUr":"اس کا مطلب ہے تمام تعریف اللہ کے لیے ہے۔","lessonLearned":null}'::jsonb)
