values ('quiz-55', 'quiz', 'basic-knowledge', 'Stars here', '', '', 'What are the stars in Little Noor?', 'لٹل نور کے ستارے کیا ہیں؟', 'The app''s stars are for learning. They are not money.', 'یہ ستارے سیکھنے کے لیے ہیں، پیسے نہیں۔', 'Basic Islamic teaching for children. A reviewer should attach the exact Quran or hadith reference before this is called verified.', 'needs_review', false, 5, 10, 'easy', null, null, '{"options":[{"id":"a","text":"Learning points, not money","icon":"sun","imageUrl":null},{"id":"b","text":"Coins to spend","icon":"heart","imageUrl":null},{"id":"c","text":"A prize of cash","icon":"star","imageUrl":null},{"id":"d","text":"A ticket","icon":"cloud","imageUrl":null}],"explanation":"The app''s stars are for learning. They are not money.","explanationUr":"یہ ستارے سیکھنے کے لیے ہیں، پیسے نہیں۔","lessonLearned":null}'::jsonb)
