values ('quiz-65', 'quiz', 'prophets', 'Birds', '', '', 'Which prophet understood the speech of birds in the Quran?', 'قرآن میں پرندوں کی بولی کس نبی کو آتی ہے؟', 'Quran 27:16. Confirm the verse.', 'سورۃ النمل 16۔ تصدیق کریں۔', 'Basic Islamic teaching for children. A reviewer should attach the exact Quran or hadith reference before this is called verified.', 'needs_review', false, 5, 10, 'easy', null, null, '{"options":[{"id":"a","text":"Sulayman","icon":"sun","imageUrl":null},{"id":"b","text":"Nuh","icon":"heart","imageUrl":null},{"id":"c","text":"Lut","icon":"star","imageUrl":null},{"id":"d","text":"Hud","icon":"cloud","imageUrl":null}],"explanation":"Quran 27:16. Confirm the verse.","explanationUr":"سورۃ النمل 16۔ تصدیق کریں۔","lessonLearned":null}'::jsonb)
