values ('quiz-70', 'quiz', 'prophets', 'Kindness', '', '', 'A true story of a prophet should be learned from where?', 'نبی کا سچا قصہ کہاں سے سیکھنا چاہیے؟', 'We do not invent words for a prophet.', 'ہم نبی کے الفاظ خود نہیں بناتے۔', 'Basic Islamic teaching for children. A reviewer should attach the exact Quran or hadith reference before this is called verified.', 'needs_review', false, 5, 10, 'easy', null, null, '{"options":[{"id":"a","text":"The Quran or a checked seerah book","icon":"sun","imageUrl":null},{"id":"b","text":"Any cartoon","icon":"heart","imageUrl":null},{"id":"c","text":"A guess","icon":"star","imageUrl":null},{"id":"d","text":"A dream we invent","icon":"cloud","imageUrl":null}],"explanation":"We do not invent words for a prophet.","explanationUr":"ہم نبی کے الفاظ خود نہیں بناتے۔","lessonLearned":null}'::jsonb)
