values ('quiz-79', 'quiz', 'quran', 'Respect', '', '', 'How do we treat a page of the Quran?', 'قرآن کے صفحے کے ساتھ کیسا برتاؤ کریں؟', 'The mushaf is respected.', 'مصحف کی عزت کی جاتی ہے۔', 'Count or name from the standard written mushaf. A reviewer should confirm it against a printed copy.', 'needs_review', false, 5, 10, 'easy', null, null, '{"options":[{"id":"a","text":"With clean hands and care","icon":"sun","imageUrl":null},{"id":"b","text":"As a coaster","icon":"heart","imageUrl":null},{"id":"c","text":"By tearing it","icon":"star","imageUrl":null},{"id":"d","text":"By drawing over the words","icon":"cloud","imageUrl":null}],"explanation":"The mushaf is respected.","explanationUr":"مصحف کی عزت کی جاتی ہے۔","lessonLearned":null}'::jsonb)
