values ('quiz-80', 'quiz', 'quran', 'Meaning', '', '', 'If you do not understand an ayah, what should you do?', 'اگر آیت سمجھ نہ آئے تو کیا کریں؟', 'Children ask a grown-up. We do not invent meanings.', 'بچہ بڑے سے پوچھے۔ معنی خود نہیں بناتے۔', 'Count or name from the standard written mushaf. A reviewer should confirm it against a printed copy.', 'needs_review', false, 5, 10, 'easy', null, null, '{"options":[{"id":"a","text":"Ask a parent or teacher","icon":"sun","imageUrl":null},{"id":"b","text":"Invent a meaning","icon":"heart","imageUrl":null},{"id":"c","text":"Erase it","icon":"star","imageUrl":null},{"id":"d","text":"Skip the Quran forever","icon":"cloud","imageUrl":null}],"explanation":"Children ask a grown-up. We do not invent meanings.","explanationUr":"بچہ بڑے سے پوچھے۔ معنی خود نہیں بناتے۔","lessonLearned":null}'::jsonb)
