values ('quiz-81', 'quiz', 'quran', 'Arabic', '', '', 'The Quran was revealed in which language?', 'قرآن کس زبان میں اترا؟', 'The Quran''s language is Arabic. Translations help us understand.', 'قرآن کی زبان عربی ہے۔ ترجمہ سمجھنے میں مدد دیتا ہے۔', 'Count or name from the standard written mushaf. A reviewer should confirm it against a printed copy.', 'needs_review', false, 7, 10, 'growing', null, null, '{"options":[{"id":"a","text":"Arabic","icon":"sun","imageUrl":null},{"id":"b","text":"Latin","icon":"heart","imageUrl":null},{"id":"c","text":"English first","icon":"star","imageUrl":null},{"id":"d","text":"Urdu first","icon":"cloud","imageUrl":null}],"explanation":"The Quran''s language is Arabic. Translations help us understand.","explanationUr":"قرآن کی زبان عربی ہے۔ ترجمہ سمجھنے میں مدد دیتا ہے۔","lessonLearned":null}'::jsonb)
