values ('quiz-82', 'quiz', 'quran', 'Translation', '', '', 'Is an English translation the same as the Arabic Quran?', 'کیا انگریزی ترجمہ عربی قرآن کے برابر ہے؟', 'A translation is a human explanation. The Arabic is the Quran.', 'ترجمہ انسان کی وضاحت ہے۔ قرآن عربی ہے۔', 'Count or name from the standard written mushaf. A reviewer should confirm it against a printed copy.', 'needs_review', false, 5, 10, 'easy', null, null, '{"options":[{"id":"a","text":"No. It is a translation and can be discussed","icon":"sun","imageUrl":null},{"id":"b","text":"Yes, every word matches perfectly","icon":"heart","imageUrl":null},{"id":"c","text":"It replaces the Arabic","icon":"star","imageUrl":null},{"id":"d","text":"It is not allowed to exist","icon":"cloud","imageUrl":null}],"explanation":"A translation is a human explanation. The Arabic is the Quran.","explanationUr":"ترجمہ انسان کی وضاحت ہے۔ قرآن عربی ہے۔","lessonLearned":null}'::jsonb)
