values ('quiz-85', 'quiz', 'quran', 'Practice', '', '', 'What is a good small goal for a child?', 'بچے کے لیے چھوٹا اچھا ہدف کیا ہے؟', 'Short, repeated practice is enough.', 'تھوڑی اور بار بار مشق کافی ہے۔', 'Count or name from the standard written mushaf. A reviewer should confirm it against a printed copy.', 'needs_review', false, 5, 10, 'easy', null, null, '{"options":[{"id":"a","text":"Learn one short surah with a parent","icon":"sun","imageUrl":null},{"id":"b","text":"Memorize the whole Quran in one hour","icon":"heart","imageUrl":null},{"id":"c","text":"Skip the Arabic","icon":"star","imageUrl":null},{"id":"d","text":"Change the words","icon":"cloud","imageUrl":null}],"explanation":"Short, repeated practice is enough.","explanationUr":"تھوڑی اور بار بار مشق کافی ہے۔","lessonLearned":null}'::jsonb)
