values ('quiz-86', 'quiz', 'history', 'Cave', '', '', 'Where did the first revelation come to Prophet Muhammad?', 'پہلی وحی نبی محمد پر کہاں آئی؟', 'This is standard seerah. Name your seerah book when you approve it.', 'یہ مشہور سیرت ہے۔ منظوری پر اپنی سیرت کی کتاب کا نام لکھیں۔', 'Basic Islamic teaching for children. A reviewer should attach the exact Quran or hadith reference before this is called verified.', 'needs_review', false, 7, 10, 'growing', null, null, '{"options":[{"id":"a","text":"The cave of Hira","icon":"sun","imageUrl":null},{"id":"b","text":"A market in Rome","icon":"heart","imageUrl":null},{"id":"c","text":"A ship","icon":"star","imageUrl":null},{"id":"d","text":"A school in Andalus","icon":"cloud","imageUrl":null}],"explanation":"This is standard seerah. Name your seerah book when you approve it.","explanationUr":"یہ مشہور سیرت ہے۔ منظوری پر اپنی سیرت کی کتاب کا نام لکھیں۔","lessonLearned":null}'::jsonb)
