values ('quiz-90', 'quiz', 'history', 'Companion', '', '', 'Who was the companion in that cave?', 'اس غار میں ساتھی کون تھے؟', 'Abu Bakr as-Siddiq. Confirm the seerah source.', 'ابو بکر صدیق۔ سیرت کے ماخذ کی تصدیق کریں۔', 'Basic Islamic teaching for children. A reviewer should attach the exact Quran or hadith reference before this is called verified.', 'needs_review', false, 5, 10, 'easy', null, null, '{"options":[{"id":"a","text":"Abu Bakr","icon":"sun","imageUrl":null},{"id":"b","text":"Abu Lahab","icon":"heart","imageUrl":null},{"id":"c","text":"Pharaoh","icon":"star","imageUrl":null},{"id":"d","text":"A merchant who refused","icon":"cloud","imageUrl":null}],"explanation":"Abu Bakr as-Siddiq. Confirm the seerah source.","explanationUr":"ابو بکر صدیق۔ سیرت کے ماخذ کی تصدیق کریں۔","lessonLearned":null}'::jsonb)
