values ('quiz-91', 'quiz', 'history', 'Masjid', '', '', 'The Prophet''s mosque was built in which city?', 'نبی کی مسجد کس شہر میں بنی؟', 'Al-Masjid an-Nabawi is in Madinah.', 'مسجدِ نبوی مدینہ میں ہے۔', 'Basic Islamic teaching for children. A reviewer should attach the exact Quran or hadith reference before this is called verified.', 'needs_review', false, 7, 10, 'growing', null, null, '{"options":[{"id":"a","text":"Madinah","icon":"sun","imageUrl":null},{"id":"b","text":"Rome","icon":"heart","imageUrl":null},{"id":"c","text":"Cairo","icon":"star","imageUrl":null},{"id":"d","text":"Granada","icon":"cloud","imageUrl":null}],"explanation":"Al-Masjid an-Nabawi is in Madinah.","explanationUr":"مسجدِ نبوی مدینہ میں ہے۔","lessonLearned":null}'::jsonb)
