values ('quiz-97', 'quiz', 'history', 'Books', '', '', 'Which books are safe places for a child''s history lesson?', 'بچے کی تاریخی سبق کے لیے محفوظ کتابیں کون سی ہیں؟', 'History about the Prophet needs a checked book.', 'نبی کی تاریخ کے لیے چیک شدہ کتاب چاہیے۔', 'Basic Islamic teaching for children. A reviewer should attach the exact Quran or hadith reference before this is called verified.', 'needs_review', false, 5, 10, 'easy', null, null, '{"options":[{"id":"a","text":"A seerah book a parent trusts","icon":"sun","imageUrl":null},{"id":"b","text":"Any video title","icon":"heart","imageUrl":null},{"id":"c","text":"A guess in a chat","icon":"star","imageUrl":null},{"id":"d","text":"A made-up comic with no review","icon":"cloud","imageUrl":null}],"explanation":"History about the Prophet needs a checked book.","explanationUr":"نبی کی تاریخ کے لیے چیک شدہ کتاب چاہیے۔","lessonLearned":null}'::jsonb)
