values ('quiz-99', 'quiz', 'history', 'Lessons', '', '', 'What should a child copy from the Prophet''s life?', 'نبی کی زندگی سے بچہ کیا اپنائے؟', 'The lessons we teach here are character lessons, not battle stories.', 'یہاں ہم اخلاق کا سبق سکھاتے ہیں، لڑائی کے قصے نہیں۔', 'Basic Islamic teaching for children. A reviewer should attach the exact Quran or hadith reference before this is called verified.', 'needs_review', false, 5, 10, 'easy', null, null, '{"options":[{"id":"a","text":"Truth, kindness, and prayer","icon":"sun","imageUrl":null},{"id":"b","text":"Anger at small things","icon":"heart","imageUrl":null},{"id":"c","text":"Waste","icon":"star","imageUrl":null},{"id":"d","text":"Mocking people","icon":"cloud","imageUrl":null}],"explanation":"The lessons we teach here are character lessons, not battle stories.","explanationUr":"یہاں ہم اخلاق کا سبق سکھاتے ہیں، لڑائی کے قصے نہیں۔","lessonLearned":null}'::jsonb)
