values ('quiz-100', 'quiz', 'history', 'Review', '', '', 'If two children''s books disagree, what should we do?', 'اگر دو بچوں کی کتابیں مختلف ہوں تو کیا کریں؟', 'Disagreement is a reason for review, not for a new story.', 'اختلاف جائزے کی وجہ ہے، نئی کہانی کی نہیں۔', 'Basic Islamic teaching for children. A reviewer should attach the exact Quran or hadith reference before this is called verified.', 'needs_review', false, 5, 10, 'easy', null, null, '{"options":[{"id":"a","text":"Ask a knowledgeable parent or teacher","icon":"sun","imageUrl":null},{"id":"b","text":"Pick the exciting one","icon":"heart","imageUrl":null},{"id":"c","text":"Mix them","icon":"star","imageUrl":null},{"id":"d","text":"Invent a third story","icon":"cloud","imageUrl":null}],"explanation":"Disagreement is a reason for review, not for a new story.","explanationUr":"اختلاف جائزے کی وجہ ہے، نئی کہانی کی نہیں۔","lessonLearned":null}'::jsonb)
