insert into public.learning_content (id, kind, category, title, arabic, transliteration, translation_en, translation_ur, body_en, body_ur, source, review_status, verified, age_min, age_max, difficulty, repeat_count, reward_points, payload)
values ('story-1', 'story', 'stories', 'Adam learns to say sorry', '', '', 'Allah taught Adam the names of things and made him the first prophet. When Adam and his wife made a mistake, they asked Allah to forgive them. Allah is the One who accepts a sincere sorry. A parent can read the story from Surah Al-Baqarah with an older child.', 'اللہ نے آدم کو چیزوں کے نام سکھائے اور انہیں پہلا نبی بنایا۔ جب آدم اور ان کی بیوی سے بھول ہوئی تو انہوں نے اللہ سے معافی مانگی۔ اللہ سچی معافی قبول کرتا ہے۔ بڑا بچہ یہ قصہ سورۃ البقرہ سے والدین کے ساتھ پڑھ سکتا ہے۔', 'Allah taught Adam the names of things and made him the first prophet. When Adam and his wife made a mistake, they asked Allah to forgive them. Allah is the One who accepts a sincere sorry. A parent can read the story from Surah Al-Baqarah with an older child.', 'اللہ نے آدم کو چیزوں کے نام سکھائے اور انہیں پہلا نبی بنایا۔ جب آدم اور ان کی بیوی سے بھول ہوئی تو انہوں نے اللہ سے معافی مانگی۔ اللہ سچی معافی قبول کرتا ہے۔ بڑا بچہ یہ قصہ سورۃ البقرہ سے والدین کے ساتھ پڑھ سکتا ہے۔', 'Quran 2:30-38. Do not add dialogue that is not in the passage you read.', 'needs_review', false, 5, 10, null, null, null, '{"lessonLearned":"When we make a mistake, we say sorry to Allah and try again."}'::jsonb)
