insert into public.learning_content (id, kind, category, title, arabic, transliteration, translation_en, translation_ur, body_en, body_ur, source, review_status, verified, age_min, age_max, difficulty, repeat_count, reward_points, payload)
values ('story-2', 'story', 'stories', 'Nuh and the big boat', '', '', 'Prophet Nuh called his people to worship Allah for a long time. Many of them refused. Allah told him to build a ship. The people who trusted Allah went aboard, and Allah saved them. Little children do not need the frightening parts.', 'نبی نوح نے اپنی قوم کو بہت دیر تک اللہ کی عبادت کی طرف بلایا۔ بہت سے لوگوں نے انکار کیا۔ اللہ نے انہیں کشتی بنانے کو کہا۔ جو لوگ اللہ پر بھروسہ کرتے تھے وہ کشتی میں سوار ہوئے اور اللہ نے انہیں بچایا۔ چھوٹے بچوں کو ڈراؤنا حصہ نہیں سنانا۔', 'Prophet Nuh called his people to worship Allah for a long time. Many of them refused. Allah told him to build a ship. The people who trusted Allah went aboard, and Allah saved them. Little children do not need the frightening parts.', 'نبی نوح نے اپنی قوم کو بہت دیر تک اللہ کی عبادت کی طرف بلایا۔ بہت سے لوگوں نے انکار کیا۔ اللہ نے انہیں کشتی بنانے کو کہا۔ جو لوگ اللہ پر بھروسہ کرتے تھے وہ کشتی میں سوار ہوئے اور اللہ نے انہیں بچایا۔ چھوٹے بچوں کو ڈراؤنا حصہ نہیں سنانا۔', 'Surah Nuh and Surah Hud. A reviewer should choose the verses for the age group.', 'needs_review', false, 5, 10, null, null, null, '{"lessonLearned":"Keep calling people to good, and trust Allah."}'::jsonb)
