insert into public.learning_content (id, kind, category, title, arabic, transliteration, translation_en, translation_ur, body_en, body_ur, source, review_status, verified, age_min, age_max, difficulty, repeat_count, reward_points, payload)
values ('story-5', 'story', 'stories', 'Yusuf tells the truth', '', '', 'Prophet Yusuf was kind, and his brothers became jealous. The Quran tells how Allah protected him and how he later forgave his brothers. Read Surah Yusuf with a parent. Skip the parts that are too grown-up.', 'نبی یوسف مہربان تھے، اور ان کے بھائی جل گئے۔ قرآن بتاتا ہے کہ اللہ نے ان کی حفاظت کی اور بعد میں انہوں نے بھائیوں کو معاف کر دیا۔ سورۃ یوسف والدین کے ساتھ پڑھیں۔ جو حصہ بڑا ہو اسے چھوڑ دیں۔', 'Prophet Yusuf was kind, and his brothers became jealous. The Quran tells how Allah protected him and how he later forgave his brothers. Read Surah Yusuf with a parent. Skip the parts that are too grown-up.', 'نبی یوسف مہربان تھے، اور ان کے بھائی جل گئے۔ قرآن بتاتا ہے کہ اللہ نے ان کی حفاظت کی اور بعد میں انہوں نے بھائیوں کو معاف کر دیا۔ سورۃ یوسف والدین کے ساتھ پڑھیں۔ جو حصہ بڑا ہو اسے چھوڑ دیں۔', 'Surah Yusuf. This retelling adds no quoted speech.', 'needs_review', false, 8, 10, null, null, null, '{"lessonLearned":"Tell the truth, and forgiveness is strong."}'::jsonb)
on conflict (id) do update set kind = excluded.kind, category = excluded.category, title = excluded.title, arabic = excluded.arabic, transliteration = excluded.transliteration, translation_en = excluded.translation_en, translation_ur = excluded.translation_ur, body_en = excluded.body_en, body_ur = excluded.body_ur, source = excluded.source, review_status = excluded.review_status, verified = excluded.verified, age_min = excluded.age_min, age_max = excluded.age_max, difficulty = excluded.difficulty, repeat_count = excluded.repeat_count, reward_points = excluded.reward_points, payload = excluded.payload
