insert into public.learning_content (id, kind, category, title, arabic, transliteration, translation_en, translation_ur, body_en, body_ur, source, review_status, verified, age_min, age_max, difficulty, repeat_count, reward_points, payload)
values ('story-6', 'story', 'stories', 'Musa''s mother trusts Allah', '', '', 'When Musa was a baby, his mother was afraid. Allah told her He would return the baby to her. She trusted Allah, and Allah brought Musa back to her arms.', 'جب موسیٰ بچے تھے تو ان کی ماں ڈری ہوئی تھیں۔ اللہ نے فرمایا کہ وہ بچہ انہیں واپس دے گا۔ انہوں نے اللہ پر بھروسہ کیا، اور اللہ نے موسیٰ کو ان کی گود میں واپس کیا۔', 'When Musa was a baby, his mother was afraid. Allah told her He would return the baby to her. She trusted Allah, and Allah brought Musa back to her arms.', 'جب موسیٰ بچے تھے تو ان کی ماں ڈری ہوئی تھیں۔ اللہ نے فرمایا کہ وہ بچہ انہیں واپس دے گا۔ انہوں نے اللہ پر بھروسہ کیا، اور اللہ نے موسیٰ کو ان کی گود میں واپس کیا۔', 'Quran 20:38-40 and 28:7-13. Confirm the verses. No extra scene was added.', 'needs_review', false, 5, 10, null, null, null, '{"lessonLearned":"A parent''s trust in Allah is a quiet kind of courage."}'::jsonb)
