insert into public.learning_content (id, kind, category, title, arabic, transliteration, translation_en, translation_ur, body_en, body_ur, source, review_status, verified, age_min, age_max, difficulty, repeat_count, reward_points, payload)
values ('story-7', 'story', 'stories', 'Musa walks with a teacher', '', '', 'Musa traveled to learn from a servant of Allah. Some events looked strange until the teacher explained them. The Quran does not give that teacher a name in the passage itself. We wait for a parent before adding any name.', 'موسیٰ اللہ کے ایک بندے سے سیکھنے گئے۔ کچھ باتیں عجیب لگیں، پھر استاد نے انہیں سمجھایا۔ اس حصے میں قرآن نے استاد کا نام نہیں لیا۔ نام جوڑنے سے پہلے والدین سے پوچھیں۔', 'Musa traveled to learn from a servant of Allah. Some events looked strange until the teacher explained them. The Quran does not give that teacher a name in the passage itself. We wait for a parent before adding any name.', 'موسیٰ اللہ کے ایک بندے سے سیکھنے گئے۔ کچھ باتیں عجیب لگیں، پھر استاد نے انہیں سمجھایا۔ اس حصے میں قرآن نے استاد کا نام نہیں لیا۔ نام جوڑنے سے پہلے والدین سے پوچھیں۔', 'Quran 18:60-82. Do not name the teacher from later reports until those reports are checked.', 'needs_review', false, 8, 10, null, null, null, '{"lessonLearned":"A student stays humble and asks."}'::jsonb)
on conflict (id) do update set kind = excluded.kind, category = excluded.category, title = excluded.title, arabic = excluded.arabic, transliteration = excluded.transliteration, translation_en = excluded.translation_en, translation_ur = excluded.translation_ur, body_en = excluded.body_en, body_ur = excluded.body_ur, source = excluded.source, review_status = excluded.review_status, verified = excluded.verified, age_min = excluded.age_min, age_max = excluded.age_max, difficulty = excluded.difficulty, repeat_count = excluded.repeat_count, reward_points = excluded.reward_points, payload = excluded.payload
