insert into public.learning_content (id, kind, category, title, arabic, transliteration, translation_en, translation_ur, body_en, body_ur, source, review_status, verified, age_min, age_max, difficulty, repeat_count, reward_points, payload)
values ('story-8', 'story', 'stories', 'Dawud remembers Allah', '', '', 'Prophet Dawud was given the Zabur and a beautiful voice for remembering Allah. He was also a king who had to be fair. Children can learn that a strong person still needs salah and fairness.', 'نبی داؤد کو زبور ملی اور اللہ کو یاد کرنے کی خوبصورت آواز ملی۔ وہ بادشاہ بھی تھے جنہیں انصاف کرنا تھا۔ بچے سیکھ سکتے ہیں کہ طاقتور آدمی کو بھی نماز اور انصاف چاہیے۔', 'Prophet Dawud was given the Zabur and a beautiful voice for remembering Allah. He was also a king who had to be fair. Children can learn that a strong person still needs salah and fairness.', 'نبی داؤد کو زبور ملی اور اللہ کو یاد کرنے کی خوبصورت آواز ملی۔ وہ بادشاہ بھی تھے جنہیں انصاف کرنا تھا۔ بچے سیکھ سکتے ہیں کہ طاقتور آدمی کو بھی نماز اور انصاف چاہیے۔', 'Quran 17:55 and 38:17-26. Leave out the harder court story for little children.', 'needs_review', false, 6, 10, null, null, null, '{"lessonLearned":"Strength still bows to Allah."}'::jsonb)
on conflict (id) do update set kind = excluded.kind, category = excluded.category, title = excluded.title, arabic = excluded.arabic, transliteration = excluded.transliteration, translation_en = excluded.translation_en, translation_ur = excluded.translation_ur, body_en = excluded.body_en, body_ur = excluded.body_ur, source = excluded.source, review_status = excluded.review_status, verified = excluded.verified, age_min = excluded.age_min, age_max = excluded.age_max, difficulty = excluded.difficulty, repeat_count = excluded.repeat_count, reward_points = excluded.reward_points, payload = excluded.payload
