insert into public.learning_content (id, kind, category, title, arabic, transliteration, translation_en, translation_ur, body_en, body_ur, source, review_status, verified, age_min, age_max, difficulty, repeat_count, reward_points, payload)
values ('story-9', 'story', 'stories', 'Sulayman and the ant', '', '', 'Prophet Sulayman could understand birds. One day an ant warned the other ants to move aside so they would not be harmed. Sulayman smiled and thanked Allah. He did not crush the tiny creatures.', 'نبی سلیمان پرندوں کی بات سمجھتے تھے۔ ایک دن ایک چیونٹی نے دوسری چیونٹیوں کو خبردار کیا کہ ہٹ جاؤ تاکہ انہیں نقصان نہ پہنچے۔ سلیمان مسکرائے اور اللہ کا شکر کیا۔ انہوں نے چھوٹے جانوروں کو نہیں کچلا۔', 'Prophet Sulayman could understand birds. One day an ant warned the other ants to move aside so they would not be harmed. Sulayman smiled and thanked Allah. He did not crush the tiny creatures.', 'نبی سلیمان پرندوں کی بات سمجھتے تھے۔ ایک دن ایک چیونٹی نے دوسری چیونٹیوں کو خبردار کیا کہ ہٹ جاؤ تاکہ انہیں نقصان نہ پہنچے۔ سلیمان مسکرائے اور اللہ کا شکر کیا۔ انہوں نے چھوٹے جانوروں کو نہیں کچلا۔', 'Quran 27:16-19. Confirm the verses before acting the story out.', 'needs_review', false, 5, 10, null, null, null, '{"lessonLearned":"Notice small creatures, and thank Allah."}'::jsonb)
on conflict (id) do update set kind = excluded.kind, category = excluded.category, title = excluded.title, arabic = excluded.arabic, transliteration = excluded.transliteration, translation_en = excluded.translation_en, translation_ur = excluded.translation_ur, body_en = excluded.body_en, body_ur = excluded.body_ur, source = excluded.source, review_status = excluded.review_status, verified = excluded.verified, age_min = excluded.age_min, age_max = excluded.age_max, difficulty = excluded.difficulty, repeat_count = excluded.repeat_count, reward_points = excluded.reward_points, payload = excluded.payload
