insert into public.learning_content (id, kind, category, title, arabic, transliteration, translation_en, translation_ur, body_en, body_ur, source, review_status, verified, age_min, age_max, difficulty, repeat_count, reward_points, payload)
values ('story-10', 'story', 'stories', 'Yunus calls from the dark', '', '', 'Prophet Yunus left his people when he was upset. He ended up in a dark place and called to Allah: there is no god except You, glory be to You, I have been among the wrongdoers. Allah saved him. Teach the meaning before the Arabic.', 'نبی یونس اپنی قوم سے ناراض ہو کر نکلے۔ وہ ایک اندھیری جگہ پہنچے اور اللہ کو پکارا: تیرے سوا کوئی معبود نہیں، تو پاک ہے، میں غلط کرنے والوں میں تھا۔ اللہ نے انہیں بچایا۔ عربی سے پہلے مطلب سکھائیں۔', 'Prophet Yunus left his people when he was upset. He ended up in a dark place and called to Allah: there is no god except You, glory be to You, I have been among the wrongdoers. Allah saved him. Teach the meaning before the Arabic.', 'نبی یونس اپنی قوم سے ناراض ہو کر نکلے۔ وہ ایک اندھیری جگہ پہنچے اور اللہ کو پکارا: تیرے سوا کوئی معبود نہیں، تو پاک ہے، میں غلط کرنے والوں میں تھا۔ اللہ نے انہیں بچایا۔ عربی سے پہلے مطلب سکھائیں۔', 'Quran 21:87. The Arabic of the dua was not fetched into this draft, so it is not pasted here.', 'needs_review', false, 7, 10, null, null, null, '{"lessonLearned":"When we are lost, we call Allah and do not give up."}'::jsonb)
on conflict (id) do update set kind = excluded.kind, category = excluded.category, title = excluded.title, arabic = excluded.arabic, transliteration = excluded.transliteration, translation_en = excluded.translation_en, translation_ur = excluded.translation_ur, body_en = excluded.body_en, body_ur = excluded.body_ur, source = excluded.source, review_status = excluded.review_status, verified = excluded.verified, age_min = excluded.age_min, age_max = excluded.age_max, difficulty = excluded.difficulty, repeat_count = excluded.repeat_count, reward_points = excluded.reward_points, payload = excluded.payload
