insert into public.learning_content (id, kind, category, title, arabic, transliteration, translation_en, translation_ur, body_en, body_ur, source, review_status, verified, age_min, age_max, difficulty, repeat_count, reward_points, payload)
values ('story-11', 'story', 'stories', 'Isa speaks with mercy', '', '', 'The Quran says Isa was a prophet and a word from Allah to Maryam. As a baby he spoke to defend his mother. He taught people to worship Allah. Muslims love him and do not worship him.', 'قرآن کہتا ہے کہ عیسیٰ نبی تھے اور مریم کی طرف اللہ کی طرف سے ایک کلمہ تھے۔ انہوں نے بچپن میں اپنی ماں کا دفاع کیا۔ انہوں نے لوگوں کو اللہ کی عبادت سکھائی۔ مسلمان انہیں مانتے ہیں اور ان کی عبادت نہیں کرتے۔', 'The Quran says Isa was a prophet and a word from Allah to Maryam. As a baby he spoke to defend his mother. He taught people to worship Allah. Muslims love him and do not worship him.', 'قرآن کہتا ہے کہ عیسیٰ نبی تھے اور مریم کی طرف اللہ کی طرف سے ایک کلمہ تھے۔ انہوں نے بچپن میں اپنی ماں کا دفاع کیا۔ انہوں نے لوگوں کو اللہ کی عبادت سکھائی۔ مسلمان انہیں مانتے ہیں اور ان کی عبادت نہیں کرتے۔', 'Quran 19:29-34 and 3:45. Confirm the verses. Do not import stories from other scriptures without review.', 'needs_review', false, 6, 10, null, null, null, '{"lessonLearned":"Love the prophets, and worship only Allah."}'::jsonb)
on conflict (id) do update set kind = excluded.kind, category = excluded.category, title = excluded.title, arabic = excluded.arabic, transliteration = excluded.transliteration, translation_en = excluded.translation_en, translation_ur = excluded.translation_ur, body_en = excluded.body_en, body_ur = excluded.body_ur, source = excluded.source, review_status = excluded.review_status, verified = excluded.verified, age_min = excluded.age_min, age_max = excluded.age_max, difficulty = excluded.difficulty, repeat_count = excluded.repeat_count, reward_points = excluded.reward_points, payload = excluded.payload
