insert into public.learning_content (id, kind, category, title, arabic, transliteration, translation_en, translation_ur, body_en, body_ur, source, review_status, verified, age_min, age_max, difficulty, repeat_count, reward_points, payload)
values ('story-12', 'story', 'stories', 'A gentle boy in Makkah', '', '', 'Before prophethood, Muhammad was known among his people as an honest young man. He looked after sheep and helped his family. This lesson uses the character people remembered. A seerah book should be named before more details are added.', 'نبوت سے پہلے محمد اپنی قوم میں ایک سچے نوجوان کے طور پر جانے جاتے تھے۔ وہ بکریاں چراتے اور گھر والوں کی مدد کرتے تھے۔ یہ سبق اس اخلاق کا ہے جو لوگ یاد رکھتے تھے۔ مزید تفصیل سے پہلے سیرت کی کتاب کا نام لکھیں۔', 'Before prophethood, Muhammad was known among his people as an honest young man. He looked after sheep and helped his family. This lesson uses the character people remembered. A seerah book should be named before more details are added.', 'نبوت سے پہلے محمد اپنی قوم میں ایک سچے نوجوان کے طور پر جانے جاتے تھے۔ وہ بکریاں چراتے اور گھر والوں کی مدد کرتے تھے۔ یہ سبق اس اخلاق کا ہے جو لوگ یاد رکھتے تھے۔ مزید تفصیل سے پہلے سیرت کی کتاب کا نام لکھیں۔', 'Standard seerah description. Needs a named children''s seerah book.', 'needs_review', false, 6, 10, null, null, null, '{"lessonLearned":"Honesty shows before anyone gives you a title."}'::jsonb)
on conflict (id) do update set kind = excluded.kind, category = excluded.category, title = excluded.title, arabic = excluded.arabic, transliteration = excluded.transliteration, translation_en = excluded.translation_en, translation_ur = excluded.translation_ur, body_en = excluded.body_en, body_ur = excluded.body_ur, source = excluded.source, review_status = excluded.review_status, verified = excluded.verified, age_min = excluded.age_min, age_max = excluded.age_max, difficulty = excluded.difficulty, repeat_count = excluded.repeat_count, reward_points = excluded.reward_points, payload = excluded.payload
