insert into public.learning_content (id, kind, category, title, arabic, transliteration, translation_en, translation_ur, body_en, body_ur, source, review_status, verified, age_min, age_max, difficulty, repeat_count, reward_points, payload)
values ('story-19', 'story', 'stories', 'The neighbor''s bowl', '', '', 'A family cooks a little extra and sends a bowl next door. Muslims teach care for neighbors. A well-known hadith says Jibril kept advising the Prophet about the neighbor. Add the exact hadith only after checking it.', 'ایک خاندان تھوڑا سا کھانا زیادہ پکا کر بغل والے گھر بھیج دیتا ہے۔ مسلمان پڑوسی کا خیال رکھنا سکھاتے ہیں۔ ایک مشہور حدیث میں جبریل بار بار پڑوسی کی وصیت کرتے ہیں۔ ٹھیک حدیث چیک کرنے کے بعد ہی شامل کریں۔', 'A family cooks a little extra and sends a bowl next door. Muslims teach care for neighbors. A well-known hadith says Jibril kept advising the Prophet about the neighbor. Add the exact hadith only after checking it.', 'ایک خاندان تھوڑا سا کھانا زیادہ پکا کر بغل والے گھر بھیج دیتا ہے۔ مسلمان پڑوسی کا خیال رکھنا سکھاتے ہیں۔ ایک مشہور حدیث میں جبریل بار بار پڑوسی کی وصیت کرتے ہیں۔ ٹھیک حدیث چیک کرنے کے بعد ہی شامل کریں۔', 'Theme of the neighbor hadith in Sahih al-Bukhari. Number and Arabic are not pasted until checked.', 'needs_review', false, 6, 10, null, null, null, '{"lessonLearned":"A neighbor is part of worship when we are fair and kind."}'::jsonb)
