values ('lesson-24', 'lesson', 'daily-life', 'Salam first', '', '', 'Assalamu alaykum is the first word at the door. Wait for the answer. Then talk.', 'دروازے پر پہلا لفظ السلام علیکم ہے۔ جواب کا انتظار کریں۔ پھر بات کریں۔', 'Assalamu alaykum is the first word at the door. Wait for the answer. Then talk.', 'دروازے پر پہلا لفظ السلام علیکم ہے۔ جواب کا انتظار کریں۔ پھر بات کریں۔', 'Draft lesson for ages 3–10. It is not a fatwa. A parent or teacher should confirm the practice their family follows.', 'needs_review', false, 3, 10, null, null, null, '{"lessonLearned":null}'::jsonb)
