values ('activity-1', 'activity', 'kindness', 'Three kind acts', '', '', 'With a parent, notice three kind acts today. Draw a star for each one on paper.', 'اس سرگرمی کی اردو ہدایت ابھی لکھی نہیں گئی۔ جائزے کے بعد شامل کریں۔', 'With a parent, notice three kind acts today. Draw a star for each one on paper.', null, 'Original classroom activity. It does not quote a hadith. Suggested stars are learning points, not money, and they are not added automatically on the Games page.', 'draft', false, 4, 7, 'easy', null, 1, '{"lessonLearned":null}'::jsonb)
