values ('activity-2', 'activity', 'daily-life', 'Salam practice', '', '', 'Practice Assalamu alaykum and the reply at home. Take turns being the person at the door.', 'اس سرگرمی کی اردو ہدایت ابھی لکھی نہیں گئی۔ جائزے کے بعد شامل کریں۔', 'Practice Assalamu alaykum and the reply at home. Take turns being the person at the door.', null, 'Draft wording for a parent or teacher to compare with a trusted book. Not marked verified.', 'needs_review', false, 3, 6, 'easy', null, 1, '{"lessonLearned":null}'::jsonb)
