values ('activity-3', 'activity', 'eating', 'Bismillah at the table', '', '', 'Before one meal, wash hands and say Bismillah together. Use the eating azkar only after a parent is content with the wording.', 'اس سرگرمی کی اردو ہدایت ابھی لکھی نہیں گئی۔ جائزے کے بعد شامل کریں۔', 'Before one meal, wash hands and say Bismillah together. Use the eating azkar only after a parent is content with the wording.', null, 'Draft wording for a parent or teacher to compare with a trusted book. Not marked verified.', 'needs_review', false, 3, 6, 'easy', null, 1, '{"lessonLearned":null}'::jsonb)
