values ('activity-5', 'activity', 'sharing', 'Toy turns', '', '', 'Set a timer for two minutes. Share one toy, then swap. No winner and no loser.', 'اس سرگرمی کی اردو ہدایت ابھی لکھی نہیں گئی۔ جائزے کے بعد شامل کریں۔', 'Set a timer for two minutes. Share one toy, then swap. No winner and no loser.', null, 'Original classroom activity. It does not quote a hadith. Suggested stars are learning points, not money, and they are not added automatically on the Games page.', 'draft', false, 3, 6, 'easy', null, 1, '{"lessonLearned":null}'::jsonb)
